// Command clipwatch keeps a clipboard history for macOS and shows it in a herdr
// popup. Run it with no arguments, or with "watch", to record the clipboard.
package main

import (
	"io"
	"log/slog"
	"os"
	"time"
	"unicode/utf8"
)

// skipMarkers lists the pasteboard types, from nspasteboard.org, that mark a
// clip as secret or machine-made. Clips carrying any of them are not recorded.
var skipMarkers = []string{
	"org.nspasteboard.ConcealedType",
	"org.nspasteboard.TransientType",
	"org.nspasteboard.AutoGeneratedType",
}

// shouldSkip reports whether the clipboard carries a skip marker. If it does,
// it also returns the marker that matched.
func shouldSkip() (string, bool) {
	for _, marker := range skipMarkers {
		if hasType(marker) {
			return marker, true
		}
	}

	return "", false
}

// watch polls the clipboard and records new text clips in the history file. It
// runs until the process is stopped.
func watch() {
	path, err := historyPath()
	if err != nil {
		fatal("error", "err", err)
	}

	h, err := Load(path)
	if err != nil {
		fatal("error", "err", err)
	}

	slog.Info("watching clipboard", "history", path, "entries", len(h.Entries))
	logf, err := openLog()
	if err != nil {
		fatal("open log", "err", err)
	}
	defer func() { _ = logf.Close() }()
	slog.SetDefault(slog.New(slog.NewTextHandler(io.MultiWriter(os.Stderr, logf), nil)))

	last := changeCount()

	for range time.Tick(300 * time.Millisecond) {
		n := changeCount()
		if n == last {
			continue
		}

		last = n
		if marker, skip := shouldSkip(); skip {
			slog.Info("skipped", "change", n, "marker", marker)
			continue
		}

		s, ok := readString()
		if !ok || !h.Add(s, time.Now()) {
			continue
		}

		if err := h.Save(path); err != nil {
			slog.Error("save failed", "err", err)
			continue
		}

		slog.Info("saved", "change", n, "chars", utf8.RuneCountInString(s), "entries", len(h.Entries))
	}

}
